-- Generated by tools/GenerateRptViews.py; edit the generator, not this file.
-- Accounts receivable aging: one row per issued invoice with a balance, bucketed by days past due as of today in the company's time zone. Needs invoice.view.
CREATE VIEW rpt.ArAging
AS
SELECT
    i.Id AS InvoiceId,
    i.InvoiceNumber AS InvoiceNumber,
    i.ClientId AS ClientId,
    COALESCE(i.ClientName, c.Name) AS ClientName,
    i.InvoiceDate AS InvoiceDate,
    i.DueDate AS DueDate,
    i.Total AS Total,
    i.BalanceDue AS BalanceDue,
    d.Days AS DaysPastDue,
    CASE WHEN d.Days = 0 THEN N'Current' WHEN d.Days <= 30 THEN N'1-30' WHEN d.Days <= 60 THEN N'31-60' WHEN d.Days <= 90 THEN N'61-90' ELSE N'Over 90' END AS AgingBucket,
    CASE WHEN d.Days = 0 THEN 0 WHEN d.Days <= 30 THEN 1 WHEN d.Days <= 60 THEN 2 WHEN d.Days <= 90 THEN 3 ELSE 4 END AS AgingBucketOrder
FROM ar.Invoice AS i
JOIN crm.Client AS c ON c.TenantId = i.TenantId AND c.Id = i.ClientId
JOIN lkp.InvoiceStatus AS s ON s.TenantId = i.TenantId AND s.Id = i.InvoiceStatusId
JOIN admin.Tenant AS tn ON tn.Id = i.TenantId
CROSS APPLY (SELECT IIF(i.DueDate < CAST(SYSUTCDATETIME() AT TIME ZONE 'UTC' AT TIME ZONE tn.TimeZoneId AS DATE), DATEDIFF(DAY, i.DueDate, CAST(SYSUTCDATETIME() AT TIME ZONE 'UTC' AT TIME ZONE tn.TimeZoneId AS DATE)), 0) AS Days) AS d
WHERE (s.SystemCode = 'ISSUED' OR s.SystemCode = 'PARTIAL') AND i.BalanceDue > 0 AND EXISTS (SELECT 1 FROM sec.fn_UserHasPermission(i.TenantId, CONVERT(INT, SESSION_CONTEXT(N'UserId')), 'invoice.view'));
GO
